  if((m=key.match(/^Kit\s+(.+)$/i))){const rest=replaceTerms(m[1],lang);return lang==='en'?rest+' kit':'Kit '+rest}
  if((m=key.match(/^Bermuda\s+(.+)$/i))){const rest=replaceTerms(m[1],lang);return lang==='en'?rest+' shorts':lang==='it'?'Shorts '+rest:'Bermuda '+rest}
  if((m=key.match(/^Agasalho\s+(.+)$/i))){const rest=replaceTerms(m[1],lang);return lang==='en'?'Jacket '+rest:lang==='it'?'Felpa '+rest:'Chaqueta '+rest}
  if((m=key.match(/^Camisa\s+(.+)$/i))){const rest=replaceTerms(m[1],lang);return lang==='en'?'Shirt '+rest:lang==='it'?'Maglia '+rest:'Camiseta '+rest}
  if((m=key.match(/^Calça\s+(.+)$/i))){const rest=replaceTerms(m[1],lang);return lang==='en'?'Pants '+rest:lang==='it'?'Pantaloni '+rest:'Pantalón '+rest}
  if(/^\d+ resultado(s)?$/i.test(key)){const n=Number(key.match(/^\d+/)[0]);return lang==='es'?n+' resultado'+(n===1?'':'s'):lang==='en'?n+' result'+(n===1?'':'s'):n+' risultat'+(n===1?'o':'i')}
  return replaceTerms(key,lang)
